@js:
/** 从缓存提取本站 /book/ID/ 链接，逐条抓详情页取真实书名 */
jsoup=org.jsoup.Jsoup.parse;
var cached=java.get('FQ_seHtml');
var html=(cached&&String(cached).length>20)?String(cached):String(src);
r=jsoup(html);
links=r.select('a[href]');
sb='<div id=\'se-results\'>';
seen={};
for(i=0;i<links.size();i++){
  a=links.get(i);
  h=String(a.attr('href')||'');
  m=h.match(/huanxiangji\.net\/book\/(\d+)\/?/i);
  if(!m) m=h.match(/huanxiangji(?:%2E|\.)net(?:%2F|\/)book(?:%2F|\/)(\d+)/i);
  if(m && !seen[m[1]]){
    seen[m[1]]=1;
    u='https://www.huanxiangji.net/book/'+m[1]+'/';
    nm='幻想姬书籍'+m[1];
    try{
      var d=String(java.ajax(u));
      var real=(d.match(/<h1>([^<]+)<\/h1>/)||[])[1]||'';
      if(!real) real=(d.match(/og:novel:book_name"\s+content="([^"]+)"/)||[])[1]||'';
      if(real && real.length>0 && real.length<80) nm=real;
    }catch(err){}
    sb+='<a href=\''+u+'\'>'+nm+'</a>\n';
  }
}
sb+='</div>';
jsoup(sb).select('a[href]')

