@js:
/**
 * WebView 通道综合搜索（绕开 OkHttp TLS 指纹被拦的死循环）
 * 六引擎全用 java.webView 真浏览器栈请求，合并结果提取本站链接
 * 仅当 WebView 返回人工验证页才弹内置浏览器兜底
 */
function FQ_isHumanVerify(b,u){
  var s=String(b||'').slice(0,6000),U=String(u||'');
  if(/_____tmd_____|\/punish\?/i.test(U)) return true;
  return /Are you not a robot|请输入验证码|验证码拦截|拖动下方滑块|请稍候，正在验证|Verify you are human|unusual traffic|cf-chl|Just a moment/i.test(s) && s.length<60000;
}
var k=String(key).trim();
/** 关键：Yandex/夸克 加 site: 反而过滤掉本站结果(实测0条)，所以统一只用原词搜六引擎；别站结果由提取规则按域名过滤 */
var q=encodeURIComponent(k);
var engines=[
  {n:'yandex',u:'https://yandex.com/search/?text='+q},
  {n:'baidu',u:'https://www.baidu.com/s?wd='+q},
  {n:'bing',u:'https://cn.bing.com/search?q='+q},
  {n:'sogou',u:'https://www.sogou.com/web?query='+q},
  {n:'quark',u:'https://quark.sm.cn/s?q='+q},
  {n:'so',u:'https://www.so.com/s?q='+q}
];
var merged='<div id=\'all-engine-results\'>';
var verifyUrl='';
var verifyNames=[];
var verifyCnt=0;
for(var i=0;i<engines.length;i++){
  var en=engines[i];
  try{
    var raw=String(java.webView(null,en.u,'JSON.stringify({h:document.documentElement.outerHTML,u:location.href})'));
    var obj=null; try{obj=JSON.parse(raw);}catch(pe){}
    var body=obj?String(obj.h||''):raw;
    var finalUrl=obj?String(obj.u||''):en.u;
    if(FQ_isHumanVerify(body,finalUrl)){
      verifyCnt++;
      verifyNames.push(en.n);
      if(!verifyUrl) verifyUrl=(finalUrl&&/^https?:/.test(finalUrl))?finalUrl:en.u;
    }else{
      /** 直接从 body 正则提取本站链接，只存链接不存整页(避免6MB缓存) */
      var re=/<a[^>]+href=["']([^"']*huanxiangji(?:\.net|%2Enet)[^"']*)["'][^>]*>([\s\S]{0,120}?)<\/a>/gi,mm,pick='';
      while((mm=re.exec(body))!=null){
        pick+='<a href="'+mm[1]+'">'+String(mm[2]).replace(/<[^>]+>/g,'').trim()+'</a>\n';
        if(pick.length>100000) break;
      }
      merged+=pick;
    }
  }catch(err){}
}
merged+='</div>';
java.put('FQ_seHtml',merged);
java.put('FQ_verifyCount',verifyCnt);
if(verifyCnt>0){
  java.put('FQ_verifyUrl',verifyUrl);
  try{java.startBrowser(verifyUrl,'🔐手动过验证');}catch(err){}
  java.put('FQ_verifyNames',verifyNames.join(','));
  try{java.longToast('【'+verifyNames.join('/')+'】需人工验证，已弹出浏览器请手动过，过完再搜一次即可补全');}catch(err){}
}
result=engines[0].u;
result
